  "distractors": [  
    {  
      "text": "It ensures faster travel times than the proposed bridge, maintaining the island’s modern appeal.",  
      "why_wrong": "The ferry advocacy group does not claim faster travel times; in fact, they acknowledge the bridge would reduce travel time to 15 minutes, while the ferry takes over two hours. This option misrepresents their position and contradicts the text."  
    },  
    {  
      "text": "It allows for greater investment in mainland infrastructure, strengthening regional economic ties.",  
      "why_wrong": "The ferry advocates focus on preserving island values and funding local services, not on investing in mainland infrastructure. This distractor misattributes their goals and shifts focus away from the island’s self-sufficiency."  
    },  
    {  
      "text": "It guarantees a permanent reduction in tourism, protecting the island’s quiet lifestyle from outsiders.",  
      "why_wrong": "The ferry advocates do not oppose tourism; they value the charm of arriving by sea and fear overdevelopment, not reduced tourism. This option falsely claims they want to cut tourism, which contradicts their support for sustainable tourism."  
    },  
    {  
      "text": "It eliminates the need for any future infrastructure projects, ensuring long-term stability.",  
      "why_wrong": "The text does not suggest the ferry upgrade would eliminate all future projects. In fact, the ferry advocates argue for freeing up funds for healthcare and education—implying ongoing investment is needed. This distractor overstates their claim."  
    },  
    {  
      "text": "It reduces the island’s reliance on fishing and horticulture by diversifying the economy through tourism.",  
      "why_wrong": "The ferry advocates do not argue for diversifying beyond fishing and horticulture; instead, they aim to preserve the existing balance. This option misrepresents their stance by suggesting a shift away from core island industries."  
    },  
    {  
      "text": "It prevents the island from becoming a target for environmental regulation due to its isolation.",  
      "why_wrong": "The text does not mention environmental regulation as a concern. The ferry advocates argue for environmental preservation, not avoidance of regulation. This distractor introduces a completely unsupported idea."  
    }  
  ]  
}
